import sys

def solve(n, b):
    # Check if the sum of b is divisible by n
    total_sum = sum(b)
    if total_sum % n != 0:
        return "NO"

    # Calculate the average value of b
    avg = total_sum // n

    # Try to find a valid sequence a
    a = []
    for i in range(n):
        if b[i] < avg:
            return "NO"
        a.append(b[i] // n)
        b[i] -= a[-1] * n

    # Check if we can distribute the remaining values
    for i in range(n):
        if b[i] != 0:
            return "NO"

    return "YES", a

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        b = list(map(int, data[index:index + n]))
        index += n
        result = solve(n, b)
        if result == "NO":
            results.append("NO")
        else:
            results.append("YES")
            results.extend(result[1])

    for result in results:
        if isinstance(result, list):
            print(" ".join(map(str, result)))
        else:
            print(result)

if __name__ == "__main__":
    main()
